/**
 * Tests for AvroSchemaConverter.convertToSchema
 */
public class AvroSchemaConverterConvertToSchemaTests {

    private static boolean isNullableBooleanSchema(Schema s) {
        if (s.getType() == Schema.Type.UNION) {
            boolean hasNull = false;
            boolean hasBoolean = false;
            for (Schema branch : s.getTypes()) {
                if (branch.getType() == Schema.Type.NULL) {
                    hasNull = true;
                }
                if (branch.getType() == Schema.Type.BOOLEAN) {
                    hasBoolean = true;
                }
            }
            return hasNull && hasBoolean;
        }
        return false;
    }

    private static boolean isBooleanSchema(Schema s) {
        if (s.getType() == Schema.Type.BOOLEAN) {
            return true;
        }
        if (s.getType() == Schema.Type.UNION) {
            return s.getTypes().stream().anyMatch(t -> t.getType() == Schema.Type.BOOLEAN);
        }
        return false;
    }

    @Test
    public void testBooleanNullablePrimitiveSchema() {
        // mock a primitive BOOLEAN type with nullable = true
        BooleanType boolTypeMock = mock(BooleanType.class);
        when(boolTypeMock.getTypeRoot()).thenReturn(LogicalTypeRoot.BOOLEAN);
        when(boolTypeMock.isNullable()).thenReturn(true);

        Schema s = AvroSchemaConverter.convertToSchema(boolTypeMock, "row", false);

        assertTrue(isNullableBooleanSchema(s), "Expected a nullable boolean schema (union with null).");
    }

    @Test
    public void testIntegerNonNullablePrimitiveSchema() {
        IntType intTypeMock = mock(IntType.class);
        when(intTypeMock.getTypeRoot()).thenReturn(LogicalTypeRoot.INTEGER);
        when(intTypeMock.isNullable()).thenReturn(false);

        Schema s = AvroSchemaConverter.convertToSchema(intTypeMock, "row", false);
        assertEquals(Schema.Type.INT, s.getType(), "Expected non-nullable int schema.");
        assertFalse(isNullableBooleanSchema(s), "Should not be nullable union for non-nullable int.");
    }

    @Test
    public void testTimestampWithoutTimeZoneLegacyMillis() {
        TimestampType tsMock = mock(TimestampType.class);
        when(tsMock.getTypeRoot()).thenReturn(LogicalTypeRoot.TIMESTAMP_WITHOUT_TIME_ZONE);
        when(tsMock.isNullable()).thenReturn(true);
        when(tsMock.getPrecision()).thenReturn(2);

        Schema s = AvroSchemaConverter.convertToSchema(tsMock, "row", true);
        String json = s.toString();
        assertTrue(json.contains("\"type\":\"long\""), "Expected long base type for timestamp.");
        assertTrue(json.contains("\"logicalType\":\"timestamp-millis\""), "Expected timestamp-millis logical type for legacy mapping.");
        assertTrue(isNullableBooleanSchema(s) || s.getType() == Schema.Type.UNION || s.getType() == Schema.Type.LONG);
    }

    @Test
    public void testTimestampWithoutTimeZoneLegacyMillisInvalidPrecision() {
        TimestampType tsMock = mock(TimestampType.class);
        when(tsMock.getTypeRoot()).thenReturn(LogicalTypeRoot.TIMESTAMP_WITHOUT_TIME_ZONE);
        when(tsMock.isNullable()).thenReturn(true);
        when(tsMock.getPrecision()).thenReturn(5);

        assertThrows(IllegalArgumentException.class, () -> {
            AvroSchemaConverter.convertToSchema(tsMock, "row", true);
        });
    }

    @Test
    public void testTimestampWithLocalTimeZoneNotLegacy() {
        LocalZonedTimestampType lzMock = mock(LocalZonedTimestampType.class);
        when(lzMock.getTypeRoot()).thenReturn(LogicalTypeRoot.TIMESTAMP_WITH_LOCAL_TIME_ZONE);
        when(lzMock.isNullable()).thenReturn(false);
        when(lzMock.getPrecision()).thenReturn(3);

        Schema s = AvroSchemaConverter.convertToSchema(lzMock, "row", false);
        String json = s.toString();
        assertTrue(json.contains("\"type\":\"long\""));
        assertTrue(json.contains("\"logicalType\":\"timestamp-millis\""));
    }

    @Test
    public void testDateNullableSchema() {
        DateType dateMock = mock(DateType.class);
        when(dateMock.getTypeRoot()).thenReturn(LogicalTypeRoot.DATE);
        when(dateMock.isNullable()).thenReturn(true);

        Schema s = AvroSchemaConverter.convertToSchema(dateMock, "row", false);
        assertEquals(Schema.Type.INT, s.getType());
        String json = s.toString();
        assertTrue(json.contains("\"logicalType\":\"date\""));
    }

    @Test
    public void testDecimalSchema() {
        DecimalType decMock = mock(DecimalType.class);
        when(decMock.getTypeRoot()).thenReturn(LogicalTypeRoot.DECIMAL);
        when(decMock.getPrecision()).thenReturn(10);
        when(decMock.getScale()).thenReturn(2);
        when(decMock.isNullable()).thenReturn(true);

        Schema s = AvroSchemaConverter.convertToSchema(decMock, "row", false);
        String json = s.toString();
        assertTrue(json.contains("\"type\":\"bytes\""));
        assertTrue(json.contains("\"precision\":10"));
        assertTrue(json.contains("\"scale\":2"));
        assertTrue(json.contains("\"logicalType\":\"decimal\""));
    }

    @Test
    public void testArraySchema() {
        ArrayType arrMock = mock(ArrayType.class);
        when(arrMock.getTypeRoot()).thenReturn(LogicalTypeRoot.ARRAY);
        // element type is BOOLEAN
        BooleanType elemMock = mock(BooleanType.class);
        when(elemMock.getTypeRoot()).thenReturn(LogicalTypeRoot.BOOLEAN);
        when(elemMock.isNullable()).thenReturn(true);
        when(arrMock.getElementType()).thenReturn(elemMock);

        Schema s = AvroSchemaConverter.convertToSchema(arrMock, "row", false);
        assertEquals(Schema.Type.ARRAY, s.getType());

        Schema inner = s.getElementType();
        assertTrue(isBooleanSchema(inner), "Expected array element to be boolean (possibly nullable).");
    }

    @Test
    public void testRowSchema() {
        // Row with a single nullable boolean field
        RowType rowMock = mock(RowType.class);
        when(rowMock.getTypeRoot()).thenReturn(LogicalTypeRoot.ROW);
        when(rowMock.isNullable()).thenReturn(true);
        when(rowMock.getFieldNames()).thenReturn(Arrays.asList("f"));

        BooleanType fieldTypeMock = mock(BooleanType.class);
        when(fieldTypeMock.getTypeRoot()).thenReturn(LogicalTypeRoot.BOOLEAN);
        when(fieldTypeMock.isNullable()).thenReturn(true);
        when(rowMock.getTypeAt(0)).thenReturn(fieldTypeMock);

        Schema s = AvroSchemaConverter.convertToSchema(rowMock, "row", false);
        assertEquals(Schema.Type.RECORD, s.getType());
        assertEquals("row", s.getName());

        List<Schema.Field> fields = s.getFields();
        assertEquals(1, fields.size());
        Schema.Field f = fields.get(0);
        assertEquals("f", f.name());

        Schema fieldSchema = f.schema();
        assertTrue(isNullableBooleanSchema(fieldSchema) || fieldSchema.getType() == Schema.Type.BOOLEAN);
    }
}

